package main

import (
    "errors"
    "fmt"
)

func Halve(n int) (int, error) {
    if n%2 != 0 {
        return 0, errors.New("число нечётное")
    }
    return n / 2, nil
}

func main() {
    half, err := Halve(10)
    if err == nil {
        fmt.Println(half)
    }
    _, err = Halve(7)
    fmt.Println(err)
}
